     1	import type { LineTiming, Storyboard } from '@dailies/core';
     2	
     3	export interface Timeline { fps: number; totalFrames: number; audioStartFrame: number; scenes: { sceneId: string; startFrame: number; durationInFrames: number }[] }
     4	
     5	export const FPS = 30;
     6	const TITLE_SEC = 2.5;
     7	const END_SEC = 3;
     8	const TAIL_SEC = 0.4;   // the last spoken scene holds this long after its last line
     9	
    10	export interface TimedLine { id: string; text: string; sceneId: string; startSec: number; endSec: number }
    11	
    12	/** Every narration line in storyboard order with its timing. A line without a timing is an error, never a guess. */
    13	export function timedLines(sb: Storyboard, timings: LineTiming[]): TimedLine[] {
    14	  const byLine = new Map(timings.map((t) => [t.lineId, t]));
    15	  return sb.scenes.flatMap((scene) =>
    16	    scene.lines.map((line) => {
    17	      const t = byLine.get(line.id);
    18	      if (!t) throw new Error(`no timing for line ${line.id} in scene ${scene.id}`);
    19	      return { id: line.id, text: line.text, sceneId: scene.id, startSec: t.startSec, endSec: t.endSec };
    20	    }),
    21	  );
    22	}
    23	
    24	/** The line being spoken `sec` seconds into the narration, or null in a pause and outside it. */
    25	export function lineAt(sb: Storyboard, timings: LineTiming[], sec: number): TimedLine | null {
    26	  return timedLines(sb, timings).find((l) => sec >= l.startSec && sec < l.endSec) ?? null;
    27	}
    28	
    29	export function buildTimeline(sb: Storyboard, timings: LineTiming[], fps: number = FPS): Timeline {
    30	  const title = sb.scenes[0];
    31	  const end = sb.scenes.at(-1);
    32	  if (title?.type !== 'title') throw new Error('storyboard must start with a title scene');
    33	  if (sb.scenes.length < 2 || end?.type !== 'end') throw new Error('storyboard must finish with an end scene');
    34	  const spoken = sb.scenes.slice(1, -1);
    35	  spoken.forEach((scene, i) => {
    36	    if (scene.type === 'title' || scene.type === 'end') throw new Error(`scene ${i + 1} (${scene.type}) cannot sit between spoken scenes`);
    37	    if (scene.lines.length === 0) throw new Error(`scene ${scene.id} has no narration lines`);
    38	  });
    39	
    40	  const lines = new Map(timedLines(sb, timings).map((l) => [l.id, l]));
    41	  const frames = (sec: number) => Math.round(sec * fps);
    42	  const audioStartFrame = frames(TITLE_SEC);
    43	
    44	  // Cut points between spoken scenes. Each is pushed at least one frame past the previous one,
    45	  // so timings that collide or run backwards still give every scene a positive length.
    46	  const cuts = [audioStartFrame];
    47	  for (const scene of spoken.slice(1)) {
    48	    const firstLine = lines.get(scene.lines[0]!.id)!;
    49	    cuts.push(Math.max(cuts.at(-1)! + 1, audioStartFrame + frames(firstLine.startSec)));
    50	  }
    51	  const lastScene = spoken.at(-1);
    52	  if (lastScene) {
    53	    const lastLine = lines.get(lastScene.lines.at(-1)!.id)!;
    54	    cuts.push(Math.max(cuts.at(-1)! + 1, audioStartFrame + frames(lastLine.endSec + TAIL_SEC)));
    55	  }
    56	
    57	  const scenes = [
    58	    { sceneId: title.id, startFrame: 0, durationInFrames: audioStartFrame },
    59	    ...spoken.map((scene, i) => ({ sceneId: scene.id, startFrame: cuts[i]!, durationInFrames: cuts[i + 1]! - cuts[i]! })),
    60	    { sceneId: end.id, startFrame: cuts.at(-1)!, durationInFrames: frames(END_SEC) },
    61	  ];
    62	  return { fps, totalFrames: cuts.at(-1)! + frames(END_SEC), audioStartFrame, scenes };
    63	}
