     2	import { timedLines } from './timeline';
     3	
     4	const pad = (n: number, width: number) => String(n).padStart(width, '0');
     5	
     6	function stamp(sec: number): string {
     7	  const ms = Math.max(0, Math.round(sec * 1000));
     8	  return `${pad(Math.floor(ms / 3_600_000), 2)}:${pad(Math.floor(ms / 60_000) % 60, 2)}:${pad(Math.floor(ms / 1000) % 60, 2)},${pad(ms % 1000, 3)}`;
     9	}
    10	
    11	/** One cue per narration line in storyboard order; `audioOffsetSec` is where the narration starts in the video. */
    12	export function toSrt(sb: Storyboard, timings: LineTiming[], audioOffsetSec: number): string {
    13	  return timedLines(sb, timings)
    14	    .map((l, i) => `${i + 1}\n${stamp(l.startSec + audioOffsetSec)} --> ${stamp(l.endSec + audioOffsetSec)}\n${l.text.replace(/\s+/g, ' ').trim()}\n`)
    15	    .join('\n');
    16	}
