    14	type Browser = Awaited<ReturnType<typeof openBrowser>>;
    15	type Composition = Awaited<ReturnType<typeof selectComposition>>;
    16	interface Stage { serveUrl: string; composition: Composition; browser: Browser }
    17	
    18	const middle = (slot: { startFrame: number; durationInFrames: number }) => slot.startFrame + Math.floor(slot.durationInFrames / 2);
