    28	}
    29	
    30	/** Bundles the composition with `publicDir`, opens one browser for every render in `fn`, and cleans both up. */
    31	async function withComposition<T>(inputProps: ReelProps, publicDir: string | null, fn: (stage: Stage) => Promise<T>): Promise<T> {
    32	  const work = await mkdtemp(join(tmpdir(), 'dailies-reel-'));
    33	  let browser: Browser | undefined;
    34	  try {
    35	    const emptyPublic = join(work, 'public');
    36	    await mkdir(emptyPublic);
    37	    const serveUrl = await bundle({ entryPoint: ENTRY_POINT, publicDir: publicDir ?? emptyPublic, outDir: join(work, 'bundle') });
    38	    await ensureBrowser();
    39	    browser = await openBrowser('chrome');
    40	    const composition = await selectComposition({ serveUrl, id: COMPOSITION_ID, inputProps, puppeteerInstance: browser });
    41	    return await fn({ serveUrl, composition, browser });
    42	  } finally {
    43	    await browser?.close({ silent: true });
    44	    await rm(work, { recursive: true, force: true });
    45	  }
    46	}
    47	
    48	/** Writes `reel.mp4`, `reel.srt` and `poster.png` into `outDir`. With `audioPath` null the cut carries captions instead of narration. */
    49	export async function renderReel(i: { storyboard: Storyboard; timings: LineTiming[]; audioPath: string | null; outDir: string }): Promise<RenderArtifact> {
    50	  const timeline = buildTimeline(i.storyboard, i.timings);   // rejects a storyboard that cannot be timed before anything is bundled
    51	  const outDir = resolve(i.outDir);
    52	  const publicDir = join(outDir, 'public');
    53	  const narration = join(publicDir, NARRATION_FILE);
    54	  await mkdir(publicDir, { recursive: true });
    55	  if (i.audioPath === null) await rm(narration, { force: true });   // a voiced attempt may have left one behind
    56	  else if (resolve(i.audioPath) !== narration) await copyFile(i.audioPath, narration);
    57	
    58	  const videoPath = join(outDir, 'reel.mp4');
    59	  const srtPath = join(outDir, 'reel.srt');
    60	  const posterPath = join(outDir, 'poster.png');
    61	  const inputProps: ReelProps = { storyboard: i.storyboard, timings: i.timings, audio: i.audioPath !== null };
    62	
    63	  await withComposition(inputProps, publicDir, async ({ serveUrl, composition, browser }) => {
    64	    await renderMedia({ serveUrl, composition, inputProps, codec: 'h264', outputLocation: videoPath, puppeteerInstance: browser });
    65	    await renderStill({ serveUrl, composition, inputProps, frame: middle(timeline.scenes[0]!), output: posterPath, puppeteerInstance: browser });
    66	  });
    67	  await writeFile(srtPath, toSrt(i.storyboard, i.timings, timeline.audioStartFrame / timeline.fps));
    68	
    69	  return { videoPath, srtPath, posterPath, durationSec: timeline.totalFrames / timeline.fps };
    70	}
    71	
    72	/**
    73	 * One PNG per scene, taken at the scene's middle frame, for the review stage.
    74	 * Stills are drawn as the captions cut: it is the tighter layout and shows every piece of text a frame can carry.
    75	 */
    76	export async function renderStills(i: { storyboard: Storyboard; timings: LineTiming[]; outDir: string }): Promise<{ sceneId: string; path: string }[]> {
    77	  const timeline = buildTimeline(i.storyboard, i.timings);
    78	  const outDir = resolve(i.outDir);
    79	  await mkdir(outDir, { recursive: true });
    80	  const inputProps: ReelProps = { storyboard: i.storyboard, timings: i.timings, audio: false };
    81	
    82	  return withComposition(inputProps, null, async ({ serveUrl, composition, browser }) => {
    83	    const stills: { sceneId: string; path: string }[] = [];
    84	    for (const [n, slot] of timeline.scenes.entries()) {
