    15	/** The area a scene may draw in. It is shorter in captions mode so the caption bar never covers content. */
    16	export function useContentBox(full = false): { width: number; height: number } {
    17	  const { width, height } = useVideoConfig();
    18	  const { captions } = useContext(ReelContext);
    19	  const bottom = captions && !full ? layout.contentBottomCaptions : layout.contentBottom;
    20	  return { width: width - 2 * layout.marginX, height: height - layout.contentTop - bottom };
