    18	  const fontSize = fitSize(textUnits(chars.join('')), { width: box.width - space.lg - stroke.bar, height: box.height - footer }, { ...size.quote, advance: advance.display, leading: leading.quote });
    19	
    20	  // Typed on over the settle window. The untyped rest is laid out but invisible, so lines never re-wrap mid-word.
    21	  const typed = Math.floor(interpolate(m.frame, [0, m.settle], [0, chars.length], CLAMP));
    22	  const cursor = 1 - m.span(1, 1.2);
    23	
    24	  return (
    25	    <Frame label="The prompt">
    26	      <div style={{ flex: 1, display: 'flex', alignItems: 'center' }}>
    27	        <div style={{ borderLeft: `${stroke.bar}px solid ${color.accent}`, paddingLeft: space.lg, fontFamily: font.display, fontSize, lineHeight: leading.quote, letterSpacing: tracking.display, overflowWrap: 'anywhere' }}>
    28	          <span>{chars.slice(0, typed).join('')}</span>
    29	          <span style={{ borderRight: `${stroke.hair}px solid ${color.accent}`, marginRight: -stroke.hair, opacity: cursor }} />
    30	          <span style={{ opacity: 0 }}>{chars.slice(typed).join('')}</span>
    31	        </div>
    32	      </div>
    33	      <Rise progress={m.enter(1)} style={{ height: footer, display: 'flex', alignItems: 'flex-end', gap: space.md }}>
    34	        <Label tone={color.accent}>Human prompt</Label>
    35	        <div style={{ fontFamily: font.mono, fontSize: size.label, lineHeight: leading.text, color: color.muted }}>session {clampEnd(scene.sessionId, SESSION_CHARS)}</div>
