600	    66	  if (rows.length <= max) return { rows, hidden: 0 };
601	    67	  const size = Math.max(0, max - 1);
602	    68	  const changed = (r: DiffRow) => (r.kind === 'add' || r.kind === 'del' ? 1 : 0);
