621	    87	  const decimals = digits.includes('.') ? digits.length - digits.indexOf('.') - 1 : 0;
622	    88	  const current = (Number(digits.replace(/,/g, '')) * Math.max(0, progress)).toFixed(decimals);
623	    89	  const [whole, fraction] = current.split('.') as [string, string | undefined];
624	    90	  const grouped = digits.includes(',') ? whole.replace(/\B(?=(\d{3})+$)/g, ',') : whole;
