const Greek: React.FC<{ k: number; unit: number; width: number }> = ({ k, unit, width }) => {
  const seed = (n: number) => { const x = Math.sin((k * 97 + n * 13 + 3) * 12.9898) * 43758.5453; return x - Math.floor(x); };
  const rows = 3 + Math.floor(seed(0) * 3);
