                  <div style={{ position: 'absolute', left: box.left, top: -strip.height / 2 + (margin - print) / 2, ...faceStyle(FACE.code, print, 1), letterSpacing: undefined, wordSpacing: print, color: color.white, opacity: film.print.opacity * take.frames }}>
                    {film.print.label.split('').join(' ')}
                  </div>
                ) : null}
                <div style={{ position: 'absolute', left: box.left, top: strip.height / 2 - margin + (margin - print) / 2, ...faceStyle(FACE.code, print, 1), color: color.white, opacity: film.print.opacity * take.frames }}>
                  {`${((k % 36) + 36) % 36 + 1}A`}
                </div>
              </>
            ) : null}
          </React.Fragment>
