            <OnFrame key={i} k={i} style={{ opacity: i <= position + 0.5 ? 1 : 0 }}>
              {step.ok ? null : <Mark kind="cross" x={box.width / 2} y={box.height / 2} width={box.width * CROSS.width} height={box.height * CROSS.height} seed={i + 3} progress={drawn} />}
              <div style={{ position: 'absolute', left: pad, top: pad, width }}>
                <Type face={FACE.code} size={size.code.ref} leading={leading.code} style={{ opacity: dim.soft, marginBottom: space.md }}>{cutToWidth(step.command, width / size.code.ref, emOf(FACE.code), false)}</Type>
                <div style={{ position: 'relative', width: 'fit-content' }}>
                  <Lines fitted={head} face={head.role.face} leading={head.role.type.leading} halo={color.film.frame} />
                  {step.ok ? <Mark kind="ring" x={widthOf(head, head.role.face) / 2} y={heightOf(head) / 2} width={widthOf(head, head.role.face) + 2 * RING.x * head.size} height={heightOf(head) + 2 * RING.y * head.size} seed={i + 11} progress={drawn} /> : null}
