            <Mark kind="cross" x={box.width / 2} y={box.height / 2 + label / 2} width={box.width * CROSS.width} height={box.height * CROSS.height} seed={3} progress={drawn} />
          ) : (
            <Mark kind="dashed" x={pad + w / 2} y={top + h / 2} width={Math.min(box.width + pad, w + 2 * RING.x)} height={Math.min(box.height - label, h + 2 * RING.y)} seed={5} progress={drawn} />
